/**
 * This implements some of the methods of openpgpSink so we can
 * intercept and record the calls to updateSecurityStatus().
 *
 * @implements {nsIMsgOpenPGPSink}
 */
const openpgpSink = {
  expectResults(maxLen) {
    this.expectedCount = maxLen;
    this.countReceived = 0;
    this.results = [];
    EnigmailSingletons.messageReader = this;
    // If there are zero expected results, we won't get calls to
    // updateSecurityStatus, and we won't resolve a promise.
    if (maxLen) {
      this._deferred = Promise.withResolvers();
      return this._deferred.promise;
    }
    return null;
  },
  isCurrentMessage() {
    return true;
  },
  isMultipartRelated() {
    return false;
  },
  displaySubPart() {
    return true;
  },
  hasUnauthenticatedParts() {
    return false;
  },
  updateSecurityStatus(exitCode, statusFlags, extStatusFlags, keyId) {
    if (statusFlags & EnigmailConstants.PGP_MIME_SIGNED) {
      this.results.push({
        type: "signed",
        status: statusFlags,
        keyId,
      });
    } else if (statusFlags & EnigmailConstants.PGP_MIME_ENCRYPTED) {
      this.results.push({
        type: "encrypted",
        status: statusFlags,
        keyId,
      });
    }

    this.countReceived++;
    this.checkFinished();
  },
  modifyMessageHeaders() {},

  checkFinished() {
    if (this.countReceived == this.expectedCount) {
      this._deferred.resolve(this.results);
    }
  },
};
